head.b:skin:
/* 
THEME: Poetry & Literary Engine (Ink & Parchment)
SYSTEM: Multiverse Poetry Generator
*/
:root {
    --midnight: #1a1c2c;
    --ink: #2c3e50;
    --paper: #fdf6e3;
    --feather: #94a3b8;
    --wine: #722f37;
}
body {
    background-color: #f1f1f1;
    color: var(--ink);
    font-family: 'EB Garamond', serif;
    margin: 0; padding: 0;
    line-height: 1.6;
}
.header-wrap {
    background: var(--midnight);
    color: var(--paper);
    padding: 60px 20px;
    text-align: center;
    border-bottom: 3px solid var(--wine);
}
.main-container {
    max-width: 800px;
    margin: -40px auto 60px;
    padding: 20px;
}
.poetry-card {
    background: var(--paper);
    border-radius: 4px;
    box-shadow: 0 10px 25px rgba(0,0,0,0.2);
    padding: 45px;
    margin-bottom: 25px;
    border: 1px solid #ddd;
    position: relative;
}
.poetry-card::after {
    content: "✒️";
    position: absolute;
    bottom: 20px; right: 20px;
    font-size: 24px; opacity: 0.3;
}
.input-group { margin-bottom: 25px; }
.input-group label {
    display: block;
    font-weight: bold;
    margin-bottom: 8px;
    color: var(--wine);
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 2px;
}
.input-group input, .input-group textarea, .input-group select {
    width: 100%;
    padding: 12px;
    border: 1px solid #ccc;
    border-radius: 0;
    font-family: 'Inter', sans-serif;
    box-sizing: border-box;
    background: #fff;
}
.input-group textarea { height: 90px; }

.options-row { display: flex; gap: 20px; flex-wrap: wrap; }
.flex-item { flex: 1; min-width: 200px; }

h2 { color: var(--midnight); text-align: center; margin-top: 0; font-style: italic; font-size: 32px; border-bottom: 1px double var(--wine); padding-bottom: 10px; }

.copy-btn {
    background: var(--wine);
    color: #fff;
    border: none;
    padding: 18px;
    cursor: pointer;
    font-weight: bold;
    width: 100%;
    transition: 0.3s;
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 3px;
}
.copy-btn:hover { background: var(--midnight); letter-spacing: 5px; }
footer { text-align: center; color: #666; padding: 20px; font-size: 12px; letter-spacing: 1px; font-style: italic; }

body.script:
function copyPrompt() {
    var title = document.getElementById("inputTitle").value || "A Silent Whisper";
    var notes = document.getElementById("inputNotes").value || "Deep emotions and vivid imagery.";
    var length = document.getElementById("inputLength").value;
    var lang = document.getElementById("inputLang").value;

    var template = (lang === 'id') ? 
                   document.getElementById("templateID").innerText : 
                   document.getElementById("templateEN").innerText;

    var finalPrompt = template
        .replace("[USER_TITLE]", title)
        .replace("[USER_NOTES]", notes)
        .replace(/\[USER_LENGTH\]/g, length);

    var tempElem = document.createElement("textarea");
    tempElem.value = finalPrompt;
    document.body.appendChild(tempElem);
    tempElem.select();
    document.execCommand("copy");
    document.body.removeChild(tempElem);

    alert("✒️ Poetic Prompt (" + length + ") copied! Let the ink flow.");
}
